package glitch

import data.glitch_lib

public_name_pattern := "(?i)(public|anonymous|unauthenticated|guest|allow_public|public_access|enable_public|anonymous_access)"
access_name_pattern := "(?i)(access|acl|policy|permission|principal|member|subject|user|group|public|anonymous)"
principal_name_pattern := "(?i)(principal|member|subject|user|group|account|identity|trusted|trust|assume|delegat)"
policy_name_pattern := "(?i)(policy|permission|permissions|action|actions|resource|resources|scope|access)"
network_name_pattern := "(?i)(cidr|source|ingress|egress|ip|network|address|range|firewall|rule)"
auth_name_pattern := "(?i)(auth|authorization|authentication|enforce|acl|policy|permissions|access_control)"
role_name_pattern := "(?i)(role|roles|privilege|privileged|access_level|group)"
trust_name_pattern := "(?i)(trust|trusted|assume|delegat|external|account)"
file_perm_name_pattern := "(?i)(mode|permission|permissions|perm|chmod|file_mode|file_permission)"

public_value_pattern := "(?i)(public|anonymous|unauthenticated|guest|allusers|allauthenticatedusers|everyone|anyone|public-read-write)"
privileged_value_pattern := "(?i)(admin|owner|root|superuser|full_access|privileged)"
disabled_value_pattern := "(?i)(none|disabled|off|no|false|disable_auth|bypass|ignore_acl|bypass_policy)"
anyall_pattern := "(?i)^(all|any|everyone|anyone|allusers|allauthenticatedusers)$"
wildcard_pattern := "(?i)^\\*$"
open_cidr_pattern := "(?i)(0\\.0\\.0\\.0/0|::/0)"
trust_value_pattern := "(?i)(external|any_account|all_accounts)"

all_keyvalues(parent)[kv] {
    kv := glitch_lib.all_attributes(parent)[_]
}
all_keyvalues(parent)[kv] {
    kv := glitch_lib.all_variables(parent)[_]
}

value_has_pattern(node, pattern) {
    glitch_lib.traverse(node, pattern)
}

value_has_wildcard(node) {
    value_has_pattern(node, wildcard_pattern)
}
value_has_anyall(node) {
    value_has_pattern(node, anyall_pattern)
}
value_has_public(node) {
    value_has_pattern(node, public_value_pattern)
}
value_has_privileged(node) {
    value_has_pattern(node, privileged_value_pattern)
}

value_has_open_network(node) {
    value_has_pattern(node, open_cidr_pattern)
}
value_has_open_network(node) {
    value_has_wildcard(node)
}
value_has_open_network(node) {
    value_has_anyall(node)
}

value_is_true(node) {
    walk(node, [_, n])
    n.ir_type == "Boolean"
    n.value == true
}
value_is_true(node) {
    walk(node, [_, n])
    n.ir_type == "String"
    regex.match("(?i)^(true|yes|on|enabled|enable|allow)$", n.value)
}

value_is_false(node) {
    walk(node, [_, n])
    n.ir_type == "Boolean"
    n.value == false
}

value_is_null_or_empty(node) {
    walk(node, [_, n])
    (n.ir_type == "Null" or n.ir_type == "Undef")
}
value_is_null_or_empty(node) {
    walk(node, [_, n])
    n.ir_type == "String"
    n.value == ""
}

value_is_disabled(node) {
    value_is_false(node)
}
value_is_disabled(node) {
    value_has_pattern(node, disabled_value_pattern)
}
value_is_disabled(node) {
    value_is_null_or_empty(node)
}

value_has_world_permission(node) {
    walk(node, [_, n])
    n.ir_type == "Integer"
    (n.value == 777 or n.value == 666)
}
value_has_world_permission(node) {
    walk(node, [_, n])
    n.ir_type == "String"
    regex.match("(?i)(^0?777$|^0?666$|public-read-write|world_writable|everyone_read|everyone_write|(?:^|(?:ugo)|o|a)\\+[rwx]{3})", n.value)
}

public_access(kv) {
    regex.match(public_name_pattern, kv.name)
    (value_is_true(kv.value) or value_has_public(kv.value))
}
public_access(kv) {
    value_has_public(kv.value)
    regex.match(access_name_pattern, kv.name)
}

wildcard_principal(kv) {
    regex.match(principal_name_pattern, kv.name)
    (value_has_wildcard(kv.value) or value_has_anyall(kv.value))
}

overly_permissive_policy(kv) {
    regex.match(policy_name_pattern, kv.name)
    (value_has_wildcard(kv.value) or value_has_anyall(kv.value) or value_has_privileged(kv.value))
}

world_permission(kv) {
    regex.match(file_perm_name_pattern, kv.name)
    value_has_world_permission(kv.value)
}

open_network(kv) {
    regex.match(network_name_pattern, kv.name)
    value_has_open_network(kv.value)
}

disabled_access(kv) {
    regex.match(auth_name_pattern, kv.name)
    value_is_disabled(kv.value)
}

privileged_role(kv) {
    regex.match(role_name_pattern, kv.name)
    value_has_privileged(kv.value)
}

trust_broad(kv) {
    regex.match(trust_name_pattern, kv.name)
    (value_has_wildcard(kv.value) or value_has_anyall(kv.value) or value_has_pattern(kv.value, trust_value_pattern))
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    kv := all_keyvalues(parent)[_]
    public_access(kv)
    result := {
        "type": "sec_invalid_bind",
        "element": kv,
        "path": parent.path,
        "description": "Public or anonymous access enabled - Access control allows unrestricted public access. (CWE-284)"
    }
}

